  {formStep===1&&<View style={{gap:10}}><Text style={styles.heading}>Şəkillər və video</Text><Text style={styles.muted}>Qalereyadan seçin və ya birbaşa kamera ilə çəkin. Veb formadakı media seçimi qaydası tətbiq olunur; dövlət nömrəsi kateqoriyasında video qəbul edilmir.</Text><View style={styles.row}><Pressable onPress={()=>void capture()} style={[styles.mediaPick,{flex:1,minWidth:140}]}><Feather name="camera" size={20} color={RED}/><Text style={styles.formLabel}>Kamera ilə çək</Text></Pressable><Pressable onPress={()=>void pick()} style={[styles.mediaPick,{flex:1,minWidth:140}]}><Feather name="image" size={20} color={RED}/><Text style={styles.formLabel}>Qalereyadan seç</Text></Pressable></View>{assets.map((asset,n)=><View key={asset.assetId||asset.uri} style={[styles.detailPad,{flexDirection:'row',alignItems:'center',gap:10,flexWrap:'wrap'}]}>{asset.type==='video'?<PromoVideo url={asset.uri}/>:<Image source={{uri:asset.uri}} style={{width:64,height:56,borderRadius:8}}/>}<Text style={[styles.meta,{flex:1,minWidth:100}]}>{asset.fileName||`Media ${n+1}`}</Text><Pressable onPress={()=>setAssets(list=>list.filter((_,i)=>i!==n))}><Text style={styles.link}>Sil</Text></Pressable></View>)}</View>}
